package org.eclipse.rdf4j.sail.extensiblestore;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.util.List;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategyFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class ExtensibleGraphAlgebraCapabilityTest {

	@Test
	void concreteBaseConnectionUsesTheKnownGraphEvaluator() {
		checkMode(baseConnectionStore(), GraphAlgebraMode.GRAPH);
	}

	@Test
	void customConnectionAndFactoryRemainConservative() {
		checkMode(new ExtensibleStoreImplForTests(), GraphAlgebraMode.LEGACY);
		ExtensibleStoreImplForTests store = baseConnectionStore();
		store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory() {
		});
		checkMode(store, GraphAlgebraMode.LEGACY);
	}

	@ParameterizedTest
	@EnumSource(GraphAlgebraMode.class)
	void subqueryInheritsGraphWithoutBindingItsLocalVariable(GraphAlgebraMode mode) {
		SailRepository repository = new SailRepository(new ExtensibleStoreImplForTests());
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createIRI("urn:graph");
			var a = vf.createIRI("urn:a");
			var c = vf.createIRI("urn:c");
			var predicate = vf.createIRI("urn:p");
			connection.add(a, predicate, vf.createIRI("urn:b"), graph);
			connection.add(c, predicate, graph, graph);
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(mode));
			for (String text : List.of(
					"SELECT ?x WHERE { GRAPH ?g { { SELECT ?x WHERE { ?x ?p ?g } } } }",
					"SELECT ?x WHERE { GRAPH ?g { { SELECT ?x WHERE { { SELECT ?x WHERE { ?x ?p ?g } } } } } }",
					"SELECT ?x WHERE { GRAPH <urn:graph> { { SELECT ?x WHERE { ?x ?p ?g } } } }")) {
				var query = connection.prepareTupleQuery(text);
				try (var rows = query.evaluate()) {
					assertThat(QueryResults.asList(rows))
							.as("%s in %s mode", text, mode)
							.extracting(row -> row.getValue("x"))
							.containsExactlyInAnyOrder(a, c);
				}
			}
			var filtered = connection.prepareTupleQuery(
					"SELECT ?x WHERE { GRAPH ?g { { SELECT ?x WHERE { ?x ?p ?g FILTER(?g=<urn:b>) } } } }");
			try (var rows = filtered.evaluate()) {
				assertThat(QueryResults.asList(rows)).extracting(row -> row.getValue("x")).containsExactly(a);
			}
			filtered.setBinding("g", graph);
			try (var rows = filtered.evaluate()) {
				assertFalse(rows.hasNext());
			}
			var alias = connection.prepareTupleQuery(
					"SELECT ?value WHERE { GRAPH ?g { { SELECT (?g AS ?value) WHERE { ?x ?p ?g } } } }");
			try (var rows = alias.evaluate()) {
				assertThat(QueryResults.asList(rows)).extracting(row -> row.getValue("value"))
						.containsExactlyInAnyOrder(vf.createIRI("urn:b"), graph);
			}
			var projected = connection.prepareTupleQuery(
					"SELECT ?x WHERE { GRAPH ?g { { SELECT * WHERE { ?x ?p ?g } } } }");
			try (var rows = projected.evaluate()) {
				assertThat(QueryResults.asList(rows)).extracting(row -> row.getValue("x")).containsExactly(c);
			}

			connection.add(vf.createIRI("urn:seed"), vf.createIRI("urn:seed"), vf.createLiteral(true), graph);
			connection.add(vf.createIRI("urn:d"), predicate, vf.createIRI("urn:b"), vf.createIRI("urn:other"));
			var correlated = connection.prepareTupleQuery(
					"SELECT ?x WHERE { GRAPH ?g { ?seed <urn:seed> ?flag . "
							+ "{ SELECT ?x WHERE { ?x <urn:p> ?g } } } }");
			try (var rows = correlated.evaluate()) {
				assertThat(QueryResults.asList(rows)).extracting(row -> row.getValue("x"))
						.containsExactlyInAnyOrder(a, c);
			}

		} finally {
			repository.shutDown();
		}
	}

	private static ExtensibleStoreImplForTests baseConnectionStore() {
		return new ExtensibleStoreImplForTests() {
			@Override
			protected NotifyingSailConnection getConnectionInternal() {
				return new ExtensibleStoreConnection<>(this);
			}
		};
	}

	private static void checkMode(ExtensibleStoreImplForTests store, GraphAlgebraMode expected) {
		SailRepository repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL,
					"SELECT ?x WHERE { GRAPH <urn:missing> { BIND(1 AS ?x) } }", null);
			assertEquals(expected, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			if (expected == GraphAlgebraMode.GRAPH) {
				try (var rows = query.evaluate()) {
					assertFalse(rows.hasNext());
				}
			}
		} finally {
			repository.shutDown();
		}
	}
}
